        int syntax_len = sizeof(syntax)/sizeof(*syntax);
        struct cil_blockinherit *inherit = NULL;
        int rc = SEPOL_ERR;

        if (db == NULL || parse_current == NULL || ast_node == NULL) {
                goto exit;
        }

        rc = __cil_verify_syntax(parse_current, syntax, syntax_len);
        if (rc != SEPOL_OK) {
                goto exit;
